@if($canManageRepairs)<script>
const customerSelect=document.getElementById('appointmentCustomer'), deviceSelect=document.getElementById('appointmentDevice');
function filterDevices(){if(!customerSelect||!deviceSelect)return;for(const option of deviceSelect.options){if(!option.value)continue;option.hidden=option.dataset.owner!==customerSelect.value;}if(deviceSelect.selectedOptions[0]?.hidden)deviceSelect.value='';}
customerSelect?.addEventListener('change',filterDevices);filterDevices();
</script>@endif
<div class="modal fade" id="deleteRecordModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog"><div class="modal-content"><form method="post" id="deleteRecordForm">@csrf @method('DELETE')<div class="modal-header"><h2 class="modal-title fs-5" id="deleteRecordTitle">Confirm deletion</h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body" id="deleteRecordMessage"></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger">Delete permanently</button></div></form></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>document.getElementById('deleteRecordModal')?.addEventListener('show.bs.modal',event=>{const b=event.relatedTarget;document.getElementById('deleteRecordForm').action=b.dataset.action;document.getElementById('deleteRecordTitle').textContent=b.dataset.title;document.getElementById('deleteRecordMessage').textContent=b.dataset.message;});window.addEventListener('pageshow',event=>{if(event.persisted)fetch('/repair/session-check',{headers:{Accept:'application/json'},cache:'no-store'}).then(response=>{if(!response.ok)window.location.replace('/login')}).catch(()=>window.location.replace('/login'))});</script>
